package main

import (
	"fmt"
	"io"
	"os"
	"strconv"
	"strings"
)

func solve(temperatures []int) []int {
	// Return days to wait for a warmer temperature (0 if never).
	return []int{}
}

func atoi(s string) int {
	v, _ := strconv.Atoi(s)
	return v
}

func parseInts(s string) []int {
	f := strings.Fields(s)
	out := make([]int, len(f))
	for i, w := range f {
		out[i] = atoi(w)
	}
	return out
}

func main() {
	data, _ := io.ReadAll(os.Stdin)
	lines := strings.Split(strings.ReplaceAll(string(data), "\r", ""), "\n")
	line := func(i int) string {
		if i < len(lines) {
			return lines[i]
		}
		return ""
	}
	temperatures := parseInts(line(0))
	result := solve(temperatures)
	parts := make([]string, len(result))
	for i, v := range result {
		parts[i] = strconv.Itoa(v)
	}
	fmt.Println(strings.Join(parts, " "))
}

